import React, { useEffect, useState } from 'react';
import Shimmer from './Shimmer';

const EffectCard = () => {
    const [products, setProducts] = useState([]);
    const [isloading,setIsloading]= useState(false);


    useEffect(() => {
        fetch('https://fakestoreapi.in/api/products')
            .then((res) => res.json())
            .then((data) => setProducts(data.products))
            .catch((err) => console.error('Error:', err));
    }, []);

    async 
      
    if (products.length === 0) {
        return <Shimmer />;
    }

    return (
        <div className="container mt-4">
            <div className="row g-4">
                {products.map((product) => (
                    <div className="col-md-4" key={product.id}>
                        <div className="card h-100 border-0 shadow rounded-4">
                            <img
                                src={product.image}
                                alt="Invalid"
                                className="img-fluid p-4"
                            />
                            <div className="card-body">
                                <h5 className="card-title fw-semibold text-uppercase">{product.brand}</h5>
                                <h5 className="card-title fw-light">
                                    <pre className='fs-6 badge badge-primary'>{product.category}</pre>
                                </h5>
                            </div>
                            <div className="card-footer bg-white border-top-0">
                                <h6 className="text-success fw-bold fs-4 badge badge-success badge-pill">
                                    ₹{product.price}
                                </h6>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default EffectCard;
